import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MonitoringWidget from "../components/MonitoringWidget";
import LogsWidget from "../components/LogsWidget";
import MLPredictionWidget from "../components/MLPredictionWidget";
import ServiceStatusWidget from "../components/ServiceStatusWidget";
import AutomationWidget from "../components/AutomationWidget";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const [darkMode, setDarkMode] = useState(false);
  const navigate = useNavigate();

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  return (
    <div className={`admin-dashboard ${darkMode ? "dark-mode" : "light-mode"}`}>

      {/* Optional: Floating fish SVGs */}
      <img src="/assets/fish1.svg" alt="fish" className="fish fish-1" />
      <img src="/assets/fish2.svg" alt="fish" className="fish fish-2" />

      {/* Optional: Background sound */}
      <audio autoPlay loop hidden>
        <source src="/assets/underwater.mp3" type="audio/mpeg" />
      </audio>

      {/* Navbar */}
      <div className="navbar">
        <h1 className="dashboard-title">⚙️ Admin Dashboard</h1>
        <div className="button-group">
          <button onClick={handleToggleDarkMode}>
            {darkMode ? "☀️ Light Mode" : "🌙 Dark Mode"}
          </button>
          <button className="logout-btn" onClick={handleLogout}>🚪 Logout</button>
        </div>
      </div>

      {/* First Row */}
      <div className="widgets-grid top-row">
        <MonitoringWidget />
        <MLPredictionWidget />
        <ServiceStatusWidget />
      </div>

      {/* Second Row */}
      <div className="widgets-grid center-row">
        <LogsWidget />
        <AutomationWidget />
      </div>
    </div>
  );
};

export default AdminDashboard;
